class Solution { private int best;public int longestUnivaluePath(TreeNode root){dfs(root);return best;}private int dfs(TreeNode node){if(node==null)return 0;int left=dfs(node.left),right=dfs(node.right);int leftArm=node.left!=null&&node.left.val==node.val?left+1:0;int rightArm=node.right!=null&&node.right.val==node.val?right+1:0;best=Math.max(best,leftArm+rightArm);return Math.max(leftArm,rightArm);} }
